update platform_pipeline
set name = #{name,jdbcType=VARCHAR},
    description = #{description,jdbcType=VARCHAR},
    canvas_json = #{canvasJson,jdbcType=LONGVARCHAR}
where id = #{id,jdbcType=VARCHAR}

mapper.select:
select 
from platform_pipeline
where cluster_id = #{clusterId,jdbcType=VARCHAR}
  and namespace = #{namespace,jdbcType=VARCHAR}
  and name = #{name,jdbcType=VARCHAR}

select 
from platform_pipeline
where cluster_id = #{clusterId,jdbcType=VARCHAR}
  and namespace = #{namespace,jdbcType=VARCHAR}
order by name

select r.status status, count(*) cnt from platform_pipeline p left join platform_pipeline_run r on r.id = ( select r2.id from platform_pipeline_run r2 where r2.pipeline_id = p.id order by r2.created_at desc, r2.id desc limit 1) where 1 = 1 and p.cluster_id = #{clusterId}
and 1 = 0 and p.namespace in #{ns}
group by r.status
